CREATE TYPE "ProjectStatus" AS ENUM ('DRAFT','ACTIVE','ON_HOLD','COMPLETED','CANCELLED');
CREATE TYPE "NeedSourceType" AS ENUM ('MANUAL','DOCUMENT_LINE');
CREATE TYPE "DemandMaturity" AS ENUM ('FORECAST','PLANNED','APPROVED','READY');
CREATE TYPE "NeedReviewStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TYPE "PlanStatus" AS ENUM ('DRAFT','ACTIVE','CLOSED');
CREATE TABLE company_disciplines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, code TEXT NOT NULL, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,code));
CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, code TEXT NOT NULL, name TEXT NOT NULL, description TEXT, location_context TEXT, status "ProjectStatus" NOT NULL DEFAULT 'DRAFT', expected_start_at TIMESTAMPTZ, expected_end_at TIMESTAMPTZ, created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,code));
CREATE TABLE project_members (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, company_membership_id UUID NOT NULL REFERENCES "CompanyMembership"(id) ON DELETE RESTRICT, status TEXT NOT NULL DEFAULT 'ACTIVE', joined_at TIMESTAMPTZ NOT NULL DEFAULT now(), left_at TIMESTAMPTZ, UNIQUE(project_id,company_membership_id));
CREATE TABLE project_member_disciplines (project_member_id UUID NOT NULL REFERENCES project_members(id) ON DELETE RESTRICT, discipline_id UUID NOT NULL REFERENCES company_disciplines(id) ON DELETE RESTRICT, PRIMARY KEY(project_member_id,discipline_id));
CREATE TABLE procurement_needs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, project_id UUID REFERENCES projects(id) ON DELETE RESTRICT, created_by UUID NOT NULL REFERENCES "User"(id), source_type "NeedSourceType" NOT NULL, source_document_id UUID REFERENCES procurement_documents(id) ON DELETE RESTRICT, source_document_line_id UUID UNIQUE REFERENCES procurement_document_lines(id) ON DELETE RESTRICT, product_identity_id UUID REFERENCES product_identities(id) ON DELETE RESTRICT, product_candidate_id UUID REFERENCES product_candidates(id) ON DELETE RESTRICT, description TEXT NOT NULL, quantity NUMERIC NOT NULL, approved_quantity NUMERIC, ready_quantity NUMERIC, unit_id UUID REFERENCES unit_definitions(id), need_date DATE NOT NULL, discipline_id UUID REFERENCES company_disciplines(id), maturity "DemandMaturity" NOT NULL DEFAULT 'FORECAST', review_status "NeedReviewStatus" NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE procurement_need_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), need_id UUID NOT NULL REFERENCES procurement_needs(id) ON DELETE RESTRICT, actor_user_id UUID NOT NULL REFERENCES "User"(id), from_maturity "DemandMaturity", to_maturity "DemandMaturity" NOT NULL, previous_quantity NUMERIC, new_quantity NUMERIC, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE procurement_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, name TEXT NOT NULL, horizon_start DATE, horizon_end DATE, status "PlanStatus" NOT NULL DEFAULT 'DRAFT', created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE procurement_plan_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, plan_id UUID NOT NULL REFERENCES procurement_plans(id) ON DELETE RESTRICT, need_id UUID NOT NULL REFERENCES procurement_needs(id) ON DELETE RESTRICT, planned_quantity NUMERIC NOT NULL, need_date DATE NOT NULL, maturity "DemandMaturity" NOT NULL, UNIQUE(plan_id,need_id));
CREATE TABLE procurement_need_approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, need_id UUID NOT NULL REFERENCES procurement_needs(id) ON DELETE RESTRICT, approver_user_id UUID NOT NULL REFERENCES "User"(id), status "NeedReviewStatus" NOT NULL, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_need_per_source_line ON procurement_needs(source_document_line_id) WHERE maturity IN ('FORECAST','PLANNED','APPROVED','READY');
CREATE UNIQUE INDEX one_active_plan_participation ON procurement_plan_items(need_id) WHERE maturity IN ('FORECAST','PLANNED','APPROVED','READY');
GRANT SELECT, INSERT, UPDATE ON company_disciplines,projects,project_members,project_member_disciplines,procurement_needs,procurement_need_history,procurement_plans,procurement_plan_items,procurement_need_approvals TO sco_runtime;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['company_disciplines','projects','project_members','project_member_disciplines','procurement_needs','procurement_need_history','procurement_plans','procurement_plan_items','procurement_need_approvals'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); END LOOP; END $$;
CREATE POLICY company_disciplines_tenant ON company_disciplines FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY projects_tenant ON projects FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY project_members_tenant ON project_members FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY project_member_disciplines_tenant ON project_member_disciplines FOR ALL TO sco_runtime USING (EXISTS (SELECT 1 FROM project_members pm WHERE pm.id=project_member_id AND pm.company_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid)) WITH CHECK (EXISTS (SELECT 1 FROM project_members pm WHERE pm.id=project_member_id AND pm.company_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid));
CREATE POLICY procurement_needs_tenant ON procurement_needs FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY procurement_need_history_tenant ON procurement_need_history FOR ALL TO sco_runtime USING (EXISTS (SELECT 1 FROM procurement_needs n WHERE n.id=need_id AND n.company_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid)) WITH CHECK (EXISTS (SELECT 1 FROM procurement_needs n WHERE n.id=need_id AND n.company_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid));
CREATE POLICY procurement_plans_tenant ON procurement_plans FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY procurement_plan_items_tenant ON procurement_plan_items FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
CREATE POLICY procurement_need_approvals_tenant ON procurement_need_approvals FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.tenant_id',true),'')::uuid);
